R(8107,"La souillure de Kezan")
R(8108,"La souillure de Kezan")
R(8109,"La souillure irrésistible de Kezan")
R(8110,"Le varech enchanté des Mers du sud")
R(8111,"Le varech enchanté des Mers du sud")
R(8112,"Le varech enchanté des Mers du sud")
R(8113,"Le varech enchanté des Mers du sud en parfait état")
R(8114,"Contrôler quatre bases",[[description="$N, vous avez pris part à la bataille du bassin d'Arathi contre nos ennemis, et acquis un grand honneur sur ce champ de bataille. Vous nous avez démontré que vous êtes un $C de grande valeur, et nos adversaires ont bien compris que vous ne vous soumettrez pas à leur félonie !$B$BPuisque vous êtes si $gdoué:douée;, je vais vous confier une tâche difficile. Je veux que vous preniez et teniez au moins quatre des bases du bassin d'Arathi. Si vous y parvenez, non seulement nous nous assurerons de la possession de ressources vitales, mais nous montrerons notre puissance à la Horde !$B$BAllez, $N, bonne chance.",objectives={"Entrez dans le bassin d'Arathi, capturez et contrôlez quatre bases simultanément, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}]])
R(8115,"Prendre cinq bases",[[description="Se battre pour s'approprier les ressources du bassin d'Arathi est une entreprise sanglante, $N. Le service que vous rendez à la Ligue d'Arathor est aussi nécessaire qu'apprécié.$B$BEt nous avons une tâche supplémentaire à vous confier.$B$BLa Ligue souhaite lancer une puissante offensive contre l'occupation du bassin d'Arathi par les Profanateurs. Nous voulons les chasser de tous les points stratégiques du champ de bataille !$B$BCe ne sera pas facile, mais si quelqu'un peut y parvenir, c'est bien vous.",objectives={"Contrôlez 5 bases du bassin d'Arathi simultanément, puis revenez voir le grand maréchal Oslight au Refuge de l'Ornière."}]])
