R(8383,"Souvenez-vous de la vallée d'Alterac !",[[description="La bataille fait rage dans la vallée d'Alterac, $n !  Vous avez fait votre part, ces temps-ci, $n ?",objectives={"La bataille fait rage dans la vallée d'Alterac, $n !  Vous avez fait votre part, ces temps-ci, $n ?"}]])
R(8384,"La revendication du bassin d'Arathi",[[description="La guerre contre la Horde diminue rapidement nos réserves, $n.  Il est vital que nous conservions le contrôle du bassin d'Arathi pour que les ressources continuent à nous arriver !  Êtes-vous déjà venue nous donner un coup de main en Arathi ?",objectives={"La guerre contre la Horde diminue rapidement nos réserves, $n.  Il est vital que nous conservions le contrôle du bassin d'Arathi pour que les ressources continuent à nous arriver !  Êtes-vous déjà venue nous donner un coup de main en Arathi ?"}]])
R(8385,"Des efforts concertés",[[description="Ah, $n.  J'espère que vous continuez à faire profiter les différents champs de bataille de votre expérience.  Au front, un grand nombre de soldats sont inspirés par des vétérans endurcis comme vous.",objectives={"Ah, $n.  J'espère que vous continuez à faire profiter les différents champs de bataille de votre expérience.  Au front, un grand nombre de soldats sont inspirés par des vétérans endurcis comme vous."}]])
R(8386,"La lutte pour le goulet des Warsong",[[description="N'oubliez pas que la bataille pour le goulet des Warsong représente bien plus que la protection de quelques arbres.  Il s'agit de conserver une frontière naturelle entre Ashenvale et les Tarrides.  Vous avez des nouvelles du champ de bataille, $n ?",objectives={"N'oubliez pas que la bataille pour le goulet des Warsong représente bien plus que la protection de quelques arbres.  Il s'agit de conserver une frontière naturelle entre Ashenvale et les Tarrides.  Vous avez des nouvelles du champ de bataille, $n ?"}]])
R(8387,"Les envahisseurs de la vallée d'Alterac",[[description="La bataille pour Alterac fait rage !  Vous devez retourner à la vallée d'Alterac et repousser une fois encore les envahisseurs du territoire des Frostwolf, $n !",objectives={"La bataille pour Alterac fait rage !  Vous devez retourner à la vallée d'Alterac et repousser une fois encore les envahisseurs du territoire des Frostwolf, $n !"}]])
R(8388,"Pour le plus grand des honneurs",[[description="Vous inspirez de nombreux et braves soldats, $n.  Vous continuez à être un exemple pour tous dans la lutte contre l'Alliance.  Quelles nouvelles m'apportez-vous de vos voyages ?",objectives={"Vous inspirez de nombreux et braves soldats, $n.  Vous continuez à être un exemple pour tous dans la lutte contre l'Alliance.  Quelles nouvelles m'apportez-vous de vos voyages ?"}]])
R(8389,"La bataille du goulet des Chanteguerres",[[description="La bataille continue de faire rage dans le goulet des Warsong, $n.  Faites votre part pour chasser les sentinelles d'Aile-argent de nos terres !",objectives={"La bataille continue de faire rage dans le goulet des Warsong, $n.  Faites votre part pour chasser les sentinelles d'Aile-argent de nos terres !"}]])
R(8390,"La conquête du bassin d'Arathi",[[description="La guerre contre la racaille de l'Alliance exige des ressources, $n ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !",objectives={"La guerre contre la racaille de l'Alliance exige des ressources, $n ! Nous ne pouvons pas nous permettre de laisser tarir nos réserves au beau milieu de la lutte.  Continuez à faire en sorte que le bassin d'Arathi reste entre nos mains !"}]])
