R(8877,"Le lanceur de fusées")
R(8878,"Des recettes de fête")
R(8879,"Les grandes comètes")
R(8880,"Les chapelets de comètes")
R(8881,"Les chapelets de grandes comètes")
R(8882,"Le lanceur de chapelets")
R(8883,"Valadar Chantétoile",[[description="Maintenant que vous avez reçu votre invitation pour la Fête lunaire, vous pouvez vous rendre à Reflet-de-Lune. Vous y trouverez de nombreux célébrants. Valadar Chantétoile et sa sœur Fariel attendent ceux qui veulent participer à la célébration au village de Havrenuit.$B$BRendez-vous à Reflet-de-Lune via la lumière lunaire supérieure et parlez à Valadar Chantétoile. Voyons quels cadeaux vous pourrez gagner pendant la fête !",objectives={"Utilisez votre Invitation à la fête lunaire dans la lumière lunaire pour vous rendre à Reflet-de-Lune. À votre arrivée, parlez à Valadar Chantétoile."}]])
R(8893,"Le Super-Oeuf-O-Matic")
R(8897,"Très chère Colara,",[[description="Je suis forcé de rester ici à monter la garde devant la porte, mais je m’inquiète pour Colara, ma bien-aimée. Je ne la vois que quelques heures, quand j’ai de la chance, et bon, regardez-moi… J’ai une paye d'officier subalterne et on peut m’expédier au front d’un moment à l’autre.$B$BEt si elle m’oubliait ? Les hommes ne manquent pas en ville. Y compris des hommes riches.$B$BBref, j’ai essayé de lui écrire. Ce n’est pas grand-chose, mais si vous pouviez lui apporter ma lettre, ce serait merveilleux.",objectives={"Apporter la Note soigneusement calligraphiée du lieutenant Heldric à Colara Dean, devant la banque de Hurlevent."}]])
R(8898,"Très chère Colara,",[[description="La dernière fois que je suis passé à Hurlevent pour les affaires de la banque, j’ai rencontré une fille et elle m’a volé mon cœur. Je n’arrête pas de penser à elle ! Je lui ai écrit une lettre – je m’y suis repris à douze fois !$B$BJe n’ai pas confiance dans la poste, et je veux être sûr qu’elle l’aura. Si vous allez dans cette direction, pourriez-vous me rendre service ?",objectives={"Apporter la Lettre froissée à Colara Dean, devant la banque de Hurlevent."}]])
R(8899,"Très chère Colara,",[[description="Comment décrire sa beauté ? Des milliers d’années à manier les mots, et me voilà à court.$B$BCes mortelles perturbent notre esprit et font de nous des fous balbutiants.$B$BJ’ai contemplé ces mots pendant trop longtemps. Je ne peux rien en tirer de plus éloquent. Non, elle doit avoir ma lettre maintenant, sans quoi un autre soupirant finira par attirer son attention.",objectives={"Apporter la Lettre immaculée à Colara Dean, devant la banque à Hurlevent."}]])
R(8900,"Très chère Elenia,",[[description="Elle était si triste. Je le voyais bien, en regardant au-delà de son état. Je veux dire, elle semblait triste. Ne l'auriez-vous pas été ?$b$bMais lorsque je lui ai parlé, nous avons créé un lien. Je n'aurais jamais cru que quelqu'un pourrait comprendre ce que je pensais, mais elle y était parvenue.$b$bQuand j'en ai parlé aux autres, ils se sont moqués de moi, alors je ne lui ai jamais reparlé. Mais elle me manque. Pouvez-vous lui apporter cette lettre de ma part ? Je veux être sûr qu'elIe lui sera remise en mains propres.",objectives={"Apporter la Note légèrement froissée à Elenia Haydon, près de la banque d'Undercity."}]])
R(8901,"Très chère Elenia,",[[description="Avez-vous déjà connu l'amour, jeune $ghomme:femme; ? Ce sentiment m'était totalement étranger, jusqu'à ce que je rencontre dernièrement une fille d'Undercity, Elenia. Il est déjà rare pour les gens comme nous de chercher ailleurs que dans notre peuple, alors ne parlons même pas des Réprouvés.$b$bMais aujourd'hui, elle hante mon esprit jour et nuit.$b$bSi cela vous est possible, pouvez-vous lui remettre cette lettre ? Je voudrais qu'elle vienne ici, à Mulgore. J'espère qu'elle dira oui.",objectives={"Apporter la Lettre écrite avec soin à Elenia Haydon, près de la banque d'Undercity."}]])
R(8902,"Très chère Elenia,",[[description="C’était dans une autre vie, mais j’ai été promis à Elenia, mon amour d’enfance. Je l’avais oubliée depuis des années mais depuis peu, je pense de plus en plus à elle.$B$BMalgré tout ce qui s’est passé, il reste peut-être un peu de place pour l’amour dans nos existences.$B$BJe suis sûr qu’elle a changé, elle aussi. Pouvez-vous lui remettre cette lettre de ma part ? Je suis trop nerveux pour la lui donner en personne.",objectives={"Apporter la Lettre pleine d'amour à Elenia Haydon, près de la banque d’Undercity."}]])
R(8903,"Les périls de l'amour",[[description="Cette épidémie d’amour a quelque chose de pas naturel. Ce n’est ni esthétique, ni convenable. Et pire, cela pourrait poser une menace pour la sécurité de l’Alliance toute entière.$B$BQue se passerait-il si les gardes étaient atteints par cette étrange maladie ? Il faut faire quelque chose.$B$BExaminez donc les gardes de Hurlevent et voyez s’ils sont devenus aussi déraisonnables que les autres.",objectives={"Obtenez une Carte de garde de Hurlevent et ramenez-là à Aristan Mottar, à Hurlevent."}]])
R(8904,"Les périls de l'amour",[[description="Il y a quelque chose de pas naturel dans cette épidémie amoureuse. Elle est écœurante, elle affaiblit nos défenses, et elle pourrait nous mettre tous en danger.$B$BQue la plupart d’entre nous soient en train de se rendre ridicule est déjà déplaisant. Mais j’ai peur que même nos gardes, qui devraient être immunisés à ce genre de chose, ne soient touchés.$B$BExaminez donc les gardes et voyez s’ils sont devenus aussi déraisonnables que les autres.",objectives={"Obtenez une Carte de garde moisie et ramenez-là à Fenstad Argyle, à Undercity."}]])
R(8905,"Une proposition sérieuse",[[description="Voilà une heureuse rencontre, $C, car j’ai quelque chose qui pourrait vous intéresser.$B$BJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.$B$BEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !",objectives={"Procurez-vous 15 Échantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Brassards du Coeur-sauvage à Deliana à Forgefer."}]])
R(8906,"Une proposition sérieuse",[[description="Voilà une heureuse rencontre, $C, car j’ai quelque chose qui pourrait vous intéresser.$B$BJ’ai en ma possession un ensemble d’armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d’une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d’une pièce d’armure plus ordinaire… et d’une petite faveur.$B$BEn ce moment, je m’intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l’hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d’or. Vous verrez, le jeu en vaut la chandelle !",objectives={"Procurez-vous 15 Échantillons de sang du Berceau-de-l'hiver et 20 pièces d’or, et apportez-les avec une paire de Manchettes de bestiaire à Deliana à Forgefer."}]])
