R(9063,"Torwa Pathfinder",[[description="Un chasseur du nom de Torwa le Guide a demandé l'aide d'un druide. Il dit que nous seuls possédons les aptitudes et le respect envers la nature nécessaires pour l'aider.$B$BUne route relie le cratère d'Un'goro au désert de Tanaris. Vous trouverez Torwa près de l'endroit où la route pénètre dans le cratère.",objectives={"Parler à Torwa le Guide au cratère d'Un'goro."}]])
R(9065,"The \"Chow\" Quest (123)aa",[[description="$Tpunk;!  Kill Kobold Vermin, 2 of em.",objectives={"Kill Kobold Vermin, 2 of em."}]])
R(9068,"Earthshatter Tunic",[[description="Me ferez-vous l'honneur de me rapporter les armures de ceux qui sont tombés en défendant ces terres ?$B$BLes armures ont été désacralisées et sont sans nul doute utilisées à mauvais escient, mais en combinant ces pièces désacralisées avec d'autres débris d'armures datant de la guerre, on peut les renouveler et en faire des armures efficace pour les batailles à venir.$B$BApportez-moi les restes d'armure de nos disparus et quelques ingrédients de purification, et vous pourrez porter l'armure de Brise-terre.$B$BCherchez dans Naxxramas.",objectives={"Rimblat Brise-terre à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est vous fabriquera une tunique de Brise-terre si vous lui apportez les objets suivants : 1 Tunique désacralisée, 25 Débris d'armure en mailles, 4 Barres d'arcanite et 3 Peaux robustes traitées."}]])
R(9069,"Earthshatter Legguards",[[description="Me ferez-vous l'honneur de me rapporter les armures de ceux qui sont tombés en défendant ces terres ?$B$BLes armures ont été désacralisées et sont sans nul doute utilisées à mauvais escient, mais en combinant ces pièces désacralisées avec d'autres débris d'armures datant de la guerre, on peut les renouveler et en faire des armures efficace pour les batailles à venir.$B$BApportez-moi les restes d'armure de nos disparus et quelques ingrédients de purification, et vous pourrez porter l'armure de Brise-terre.$B$BCherchez dans Naxxramas.",objectives={"Rimblat Brise-terre à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est vous fabriquera un kilt de Brise-terre si vous lui apportez les objets suivants : 1 paire de Cuissards désacralisés, 20 Débris d'armure en mailles, 3 Barres d'arcanite et 5 Peaux robustes traitées."}]])
