R(9318,"Huile de sorcier bénie")
R(9319,"Une lumière au sein des ombres",[[description="Nous ne sommes pas les seuls à célébrer cette fête, $N. Toutes les créatures, toutes les cultures, sont touchées par les flammes. Même dans les lieux les plus sombres, des feux sont allumés.$B$BSi vous souhaitez le vérifier par vous-même, voyagez dans les profondeurs. Cherchez les feux de joie qui brûlent dans Stratholme, dans la Scholomance, parmi les ogres de Hache-tripes et dans les salles du pic Rochenoire lui-même ; j'attendrai votre retour.",objectives={"Trouvez et touchez les feux de joie situés au pic Rochenoire, à Hache-tripes, dans la Scholomance et à Stratholme. Puis retournez voir le gardien des flammes de la fête."}]])
R(9320,"Potion de mana majeure")
R(9321,"Potion de soins majeure")
R(9322,"Feux sauvages en Kalimdor",[[description="La fête du Feu du solstice d'été est célébrée partout en Azeroth, et les terres contrastées de Kalimdor ne font guère exception. À vous voir, un voyage ne vous ferait pas de mal.$B$BLe solstice d'été ne peut être pleinement apprécié que si vous voyez les grands feux bleutés de par le monde. Les célébrants ont allumé des feux dans l'ouest de la froide région de Berceau-de-l'hiver, dans le nord-est d'Azshara, près du Repos des Vaillants dans les terres désolées de Silithus, et près de l'entrée de la luxuriante contrée d'Un'Goro. Revenez quand vous aurez achevé votre voyage.",objectives={"Visitez les campements du solstice d'été en Azshara, en Silithus, au cratère d'Un'Goro et à Berceau-de-l'Hiver, puis revenez voir le Gardien des flammes."}]])
R(9323,"Feux sauvages dans les Royaumes de l'est",[[description="Notre célébration de la flamme se répand à travers les territoires, $c. Aucun lieu n’est assez éloigné pour ne pas ressentir la chaleur de notre fête, et les plus grands feux brillent de flammes d’un bleu intense. Allez les voir.$b$bVous en trouverez un juste au nord du pic Blackrock. Les autres sont près d’une ville en ruine au cœur des Maleterres de l’est, le long de la route des falaises dans les montagneuses Hinterlands, et sur la voie de la Porte des ténèbres dans les Terres foudroyées.$b$bRevenez une fois que votre voyage sera terminé.",objectives={"Rendez visite aux campements de la fête du Feu situés dans les Terres foudroyées, les Maleterres de l’est, les Hinterlands, et la gorge des Vents brûlants, puis allez parler au gardien des flammes de la fête."}]])
R(9324,"Voler la flamme d'Orgrimmar",[[description="Cette flamme, dérobée au cœur même d'Orgrimmar, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Maître des traditions saura sûrement vous en dire plus...",objectives={"Rapportez la Flamme d'Orgrimmar au Maître des traditions."}]])
R(9325,"Voler la flamme de Thunder Bluff",[[description="Cette flamme, dérobée aux chamans des Pitons du Tonnerre, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Maître des traditions saura sûrement vous en dire plus...",objectives={"Rapportez la flamme des Pitons du Tonnerre au Maître des traditions."}]])
R(9326,"Voler la flamme d'Undercity",[[description="Cette flamme, dérobée dans les ruines au-dessus de Fossoyeuse, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Maître des traditions saura sûrement vous en dire plus...",objectives={"Rapportez la flamme de Fossoyeuse au Maître des traditions."}]])
R(9330,"Voler la flamme de Stormwind",[[description="Cette flamme, dérobée au cœur même de Hurlevent, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Conteur de la fête saura sûrement vous en dire plus...",objectives={"Rapportez la flamme de Hurlevent au Conteur de la fête."}]])
R(9331,"Voler la flamme d'Ironforge",[[description="Cette flamme, dérobée au cœur même de Forgefer, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Conteur de la fête saura sûrement vous en dire plus...",objectives={"Rapportez la flamme de Forgefer au Conteur de la fête."}]])
